```json
{
  "question": "You are given a list of $k$ sorted lists of integers, and a target integer $m$. Find the $m$-th smallest element (1-indexed) across all the lists combined. You can assume that the total number of elements across all lists is at least $m$, and all input lists are already sorted in ascending order.",
  "function_name": "kth_smallest_in_sorted_lists",
  "signature": "def kth_smallest_in_sorted_lists(lists: list[list[int]], m: int) -> int",
  "checker": "exact",
  "reference_solution": "def kth_smallest_in_sorted_lists(lists: list[list[int]], m: int) -> int:\n    import heapq\n    min_heap = []\n    for i, lst in enumerate(lists):\n        if lst:\n            heapq.heappush(min_heap, (lst[0], i, 0))\n    \n    val = 0\n    for _ in range(m):\n        val, r_idx, c_idx = heapq.heappop(min_heap)\n        if c_idx + 1 < len(lists[r_idx]):\n            heapq.heappush(min_heap, (lists[r_idx][c_idx + 1], r_idx, c_idx + 1))\n    return val",
  "cases": [
    {
      "args_json": "[[[1, 4, 7], [2, 5, 8], [3, 6, 9]], 5]",
      "expected_json": "5",
      "note": "Finds the 5th smallest element among three standard 3-element lists."
    },
    {
      "args_json": "[[[2, 6, 8], [3, 4, 10]], 1]",
      "expected_json": "2",
      "note": "Finds the 1st smallest element (minimum)."
    },
    {
      "args_json": "[[[10, 20, 30], [5, 15, 25]], 4]",
      "expected_json": "20",
      "note": "Lists start with different minimum elements, checking inter-list ordering."
    },
    {
      "args_json": "[[[1]], 1]",
      "expected_json": "1",
      "note": "Minimal input with a single list of length 1 and m = 1."
    },
    {
      "args_json": "[[[1, 3, 5], [2, 4, 6], [0, 7, 8]], 6]",
      "expected_json": "5",
      "note": "Lists do not have to start globally sorted relative to each other."
    },
    {
      "args_json": "[[[1, 2], [3, 4], [5, 6]], 6]",
      "expected_json": "6",
      "note": "Finds the maximum element across all lists."
    }
  ]
}
